import { HttpClient } from '@angular/common/http';
import { Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, Observable, catchError, map, switchMap, tap } from 'rxjs';
import { API_URL } from '../api';
import { formatShowDate } from '../dates';
import { Movie, Screening } from '../models';
import { ToastService } from '../toast';
import { buildAuditorium, CouchCell, SeatCell, seatIdsOf } from './auditorium';

/** A booking holds at most this many seats; a couch counts as 2. */
export const MAX_SEATS_PER_BOOKING = 10;
const MAX_SEATS_MESSAGE = `Maximum ${MAX_SEATS_PER_BOOKING} seats per booking`;

const LEGEND = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
] as const;

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toast = inject(ToastService);

  protected readonly screening = signal<Screening | null>(null);
  /** Seat identifiers (`R<row>C<column>`) of the current selection. */
  private readonly selectedSeats = signal<ReadonlySet<string>>(new Set());

  protected readonly legend = LEGEND;
  protected readonly selectedCount = computed(() => this.selectedSeats().size);

  protected readonly showDate = computed(() => {
    const screening = this.screening();
    return screening ? formatShowDate(screening.date, screening.time) : '';
  });

  protected readonly rows = computed(() =>
    buildAuditorium(this.screening()?.occupiedSeats ?? [], this.selectedSeats()),
  );

  /** One line per row with a selection, in ascending row and column order. */
  protected readonly selectedRows = computed(() =>
    this.rows()
      .map(({ row, cells }) => ({
        row,
        seats: cells.flatMap((cell) => {
          if (cell.kind === 'seat' && cell.state === 'selected') {
            return [String(cell.column)];
          }
          if (cell.kind === 'couch' && cell.state === 'selected') {
            return [`${cell.columnStart}-${cell.columnEnd}`];
          }
          return [];
        }),
      }))
      .filter((line) => line.seats.length > 0),
  );

  constructor() {
    this.route.paramMap
      .pipe(
        map((params) => params.get('id') ?? ''),
        tap(() => this.screening.set(null)),
        switchMap((id) =>
          this.loadScreening(id).pipe(
            catchError(() => {
              void this.router.navigateByUrl('/');
              return EMPTY;
            }),
          ),
        ),
        takeUntilDestroyed(),
      )
      .subscribe((screening) => this.screening.set(screening));
  }

  /** Selects or deselects a seat or couch; a couch is always toggled as one unit. */
  protected toggle(cell: SeatCell | CouchCell): void {
    if (cell.state === 'unavailable') {
      return;
    }

    const ids = seatIdsOf(cell);
    const selected = new Set(this.selectedSeats());

    if (cell.state === 'selected') {
      ids.forEach((id) => selected.delete(id));
    } else if (selected.size + ids.length > MAX_SEATS_PER_BOOKING) {
      this.toast.show(MAX_SEATS_MESSAGE);
      return;
    } else {
      ids.forEach((id) => selected.add(id));
    }
    this.selectedSeats.set(selected);
  }

  protected cancel(): void {
    this.selectedSeats.set(new Set());
    void this.router.navigateByUrl('/');
  }

  protected continueToSummary(): void {
    const id = this.screening()?.id;
    if (id === undefined || this.selectedCount() === 0) {
      return;
    }
    void this.router.navigate(['/screenings', id, 'summary']);
  }

  /** Loads the screening and its movie; the page only needs the screening, but both must load. */
  private loadScreening(id: string): Observable<Screening> {
    return this.http.get<Screening>(`${API_URL}/screenings/${id}`).pipe(
      switchMap((screening) =>
        this.http.get<Movie>(`${API_URL}/movies/${screening.movieId}`).pipe(map(() => screening)),
      ),
    );
  }
}
/** Seat state as drawn on the map. */
export type SeatState = 'available' | 'accessible' | 'selected' | 'unavailable';

/** A couch is never accessible. */
export type CouchState = Exclude<SeatState, 'accessible'>;

export const ROW_COUNT = 15;
export const COLUMN_COUNT = 24;

/** Rows 1 to 10 have no seats in columns 1 to 4: that space is the entrance. */
const ENTRANCE_LAST_ROW = 10;
const COUCH_ROW = 15;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;

/**
 * The auditorium is a CSS grid with 28 tracks per row: track 1 is the left row label, tracks
 * 2–5 are columns 1–4, track 6 is the left aisle, tracks 7–22 are columns 5–20, track 23 is the
 * right aisle, tracks 24–27 are columns 21–24 and track 28 is the right row label.
 */
const LEFT_AISLE_TRACK = 6;
const RIGHT_AISLE_TRACK = 23;

interface CellBase {
  row: number;
  /** CSS `grid-column` value, e.g. `2 / 3`. */
  gridColumn: string;
}

export interface SeatCell extends CellBase {
  kind: 'seat';
  column: number;
  state: SeatState;
}

export interface CouchCell extends CellBase {
  kind: 'couch';
  columnStart: number;
  columnEnd: number;
  state: CouchState;
}

export interface AisleCell extends CellBase {
  kind: 'aisle';
}

export type AuditoriumCell = SeatCell | CouchCell | AisleCell;

export interface AuditoriumRow {
  row: number;
  cells: AuditoriumCell[];
}

/** Grid track holding the given seat column. */
function columnTrack(column: number): number {
  if (column <= 4) {
    return column + 1;
  }
  if (column <= 20) {
    return column + 2;
  }
  return column + 3;
}

/** `grid-column` value covering the tracks of columns `first` to `last` (inclusive). */
function columnSpan(first: number, last: number): string {
  return `${columnTrack(first)} / ${columnTrack(last) + 1}`;
}

function trackSpan(track: number): string {
  return `${track} / ${track + 1}`;
}

/** Seat identifiers (`R<row>C<column>`) covered by a seat or couch; a couch covers two. */
export function seatIdsOf(cell: SeatCell | CouchCell): string[] {
  if (cell.kind === 'seat') {
    return [seatId(cell.row, cell.column)];
  }
  return [seatId(cell.row, cell.columnStart), seatId(cell.row, cell.columnEnd)];
}

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

/**
 * Builds the 15 rows of the auditorium from the occupied seat identifiers (`R<row>C<column>`)
 * and the selected ones. Couches in row 15 are built as one cell per pair of columns (1–2,
 * 3–4, … 23–24).
 */
export function buildAuditorium(
  occupiedSeats: readonly string[],
  selectedSeats: ReadonlySet<string> = new Set(),
): AuditoriumRow[] {
  const occupied = new Set(occupiedSeats);
  const isOccupied = (row: number, column: number) => occupied.has(seatId(row, column));
  const isSelected = (row: number, column: number) => selectedSeats.has(seatId(row, column));

  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const row = index + 1;
    const cells: AuditoriumCell[] = [
      { kind: 'aisle', row, gridColumn: trackSpan(LEFT_AISLE_TRACK) },
      { kind: 'aisle', row, gridColumn: trackSpan(RIGHT_AISLE_TRACK) },
    ];

    for (let column = 1; column <= COLUMN_COUNT; column++) {
      if (row <= ENTRANCE_LAST_ROW && column <= 4) {
        continue;
      }

      if (row === COUCH_ROW) {
        if (column % 2 === 1) {
          cells.push({
            kind: 'couch',
            row,
            columnStart: column,
            columnEnd: column + 1,
            gridColumn: columnSpan(column, column + 1),
            state: couchState(
              isOccupied(row, column) || isOccupied(row, column + 1),
              isSelected(row, column) || isSelected(row, column + 1),
            ),
          });
        }
        continue;
      }

      cells.push({
        kind: 'seat',
        row,
        column,
        gridColumn: columnSpan(column, column),
        state: seatState(row, column, isOccupied(row, column), isSelected(row, column)),
      });
    }

    return { row, cells };
  });
}

function couchState(occupied: boolean, selected: boolean): CouchState {
  if (occupied) {
    return 'unavailable';
  }
  return selected ? 'selected' : 'available';
}

function seatState(row: number, column: number, occupied: boolean, selected: boolean): SeatState {
  if (occupied) {
    return 'unavailable';
  }
  if (selected) {
    return 'selected';
  }
  const accessible =
    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
  return accessible ? 'accessible' : 'available';
}

@if (screening()) {
  <section class="seat-selection-page">
    <h1 class="title" data-testid="seat-map-title">Choose your seats</h1>
    <p class="subtitle" data-testid="seat-map-subtitle">Show Date: {{ showDate() }}</p>

    <div class="auditorium">
      <p class="seat-limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>
      <div class="screen" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (row of rows(); track row.row) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.row">
            <span class="row-label row-label-left" data-testid="row-label-left" [attr.data-row]="row.row">{{ row.row }}</span>
            @for (cell of row.cells; track $index) {
              @switch (cell.kind) {
                @case ('seat') {
                  <button
                    type="button"
                    class="seat"
                    data-testid="seat"
                    [style.grid-column]="cell.gridColumn"
                    [attr.data-row]="cell.row"
                    [attr.data-column]="cell.column"
                    [attr.data-state]="cell.state"
                    [disabled]="cell.state === 'unavailable'"
                    (click)="toggle(cell)"
                  >{{ cell.column }}</button>
                }
                @case ('couch') {
                  <button
                    type="button"
                    class="couch"
                    data-testid="couch"
                    [style.grid-column]="cell.gridColumn"
                    [attr.data-row]="cell.row"
                    [attr.data-column-start]="cell.columnStart"
                    [attr.data-column-end]="cell.columnEnd"
                    [attr.data-state]="cell.state"
                    [disabled]="cell.state === 'unavailable'"
                    (click)="toggle(cell)"
                  >{{ cell.columnStart }}-{{ cell.columnEnd }}</button>
                }
                @case ('aisle') {
                  <div
                    class="aisle"
                    data-testid="aisle"
                    [style.grid-column]="cell.gridColumn"
                    [attr.data-row]="cell.row"
                  ></div>
                }
              }
            }
            <span class="row-label row-label-right" data-testid="row-label-right" [attr.data-row]="row.row">{{ row.row }}</span>
          </div>
        }
      </div>
    </div>

    <ul class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <li class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
          <span class="legend-swatch"></span>
          <span>{{ item.label }}</span>
        </li>
      }
    </ul>

    <div class="selected-seats" data-testid="selected-seats">
      <p class="selected-seats-count" data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</p>
      @for (line of selectedRows(); track line.row) {
        <p class="selected-seats-row" data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.seats.join(', ') }}</p>
      }
    </div>

    <div class="actions">
      <button mat-stroked-button type="button" data-testid="cancel-button" (click)="cancel()">Cancel</button>
      <button
        mat-flat-button
        type="button"
        data-testid="continue-button"
        [disabled]="selectedCount() === 0"
        (click)="continueToSummary()"
      >Continue</button>
    </div>
  </section>
}
