  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
}

.legend-swatch {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}

.selected-seats {
  display: flex;
  flex-direction: column;
  align-items: center;
